def below_zero(operations: list[int]) -> bool:
    def stats(lo: int, hi: int) -> tuple[int, int]:
        if hi - lo == 1:
            return (operations[lo], operations[lo])
        mid: int = (lo + hi) // 2
        left: tuple[int, int] = stats(lo, mid)
        right: tuple[int, int] = stats(mid, hi)
        total: int = left[0] + right[0]
        cand: int = left[0] + right[1]
        m: int = left[1] if left[1] < cand else cand
        return (total, m)

    n: int = len(operations)
    if n == 0:
        return False
    result: tuple[int, int] = stats(0, n)
    return result[1] < 0

