def go(s: str, i: int, depth: int, mx: int, in_group: bool, acc: list[int]) -> list[int]:
    if i == len(s):
        if in_group:
            return acc + [mx]
        return acc
    c: str = s[i]
    if c == ' ':
        if in_group:
            return go(s, i + 1, 0, 0, False, acc + [mx])
        return go(s, i + 1, 0, 0, False, acc)
    if c == '(':
        d: int = depth + 1
        nm: int = d if d > mx else mx
        return go(s, i + 1, d, nm, True, acc)
    if c == ')':
        return go(s, i + 1, depth - 1, mx, True, acc)
    return go(s, i + 1, depth, mx, True, acc)


